package com.keepcalm.placementportal.controller;import com.keepcalm.placementportal.api.PagedResponse;import com.keepcalm.placementportal.service.AnalyticsService;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
public final class AnalyticsController{private AnalyticsController(){}@RestController@RequestMapping("/api/v1/admin/analytics")@RequiredArgsConstructor public static class Analytics{private final AnalyticsService service;@GetMapping("/overview")public Map<String,Object> overview(){return service.overview();}@GetMapping("/applications")public List<Map<String,Object>> applications(){return service.applicationAnalytics();}@GetMapping("/placements-by-branch")public List<Map<String,Object>> branch(){return service.placementsByBranch();}@GetMapping("/packages")public Map<String,Object> packages(){return service.packages();}@GetMapping("/company-performance")public List<Map<String,Object>> companies(){return service.companyPerformance();}@GetMapping(value="/export",produces="text/csv")public ResponseEntity<byte[]> export(){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=analytics.csv").body(service.export());}}@RestController@RequestMapping("/api/v1/admin")@RequiredArgsConstructor public static class Dashboard{private final AnalyticsService service;@GetMapping("/dashboard")public Map<String,Object> dashboard(){return service.dashboard();}@GetMapping("/action-items")public List<Map<String,Object>> actionItems(){return service.actionItems();}@GetMapping("/activity")public PagedResponse<Map<String,Object>> activity(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return service.activity(p);}}}
